problems.solution:
def num_grad(L, x, y, h=1e-5):
    gx = (L(x + h, y) - L(x - h, y)) / (2 * h)
    gy = (L(x, y + h) - L(x, y - h)) / (2 * h)
    return [gx, gy]

def descend(L, x, y, lr, steps):
    for _ in range(steps):
        gx, gy = num_grad(L, x, y)
        x, y = x - lr * gx, y - lr * gy
    return x, y
